package com.portfolio.editor.controller;
import com.portfolio.editor.dto.VideoResponse; import com.portfolio.editor.model.Video; import com.portfolio.editor.repository.VideoRepository; import com.portfolio.editor.service.CloudinaryService; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api/videos") public class VideoController {
 private final VideoRepository repo; private final CloudinaryService cloud; public VideoController(VideoRepository repo,CloudinaryService cloud){this.repo=repo;this.cloud=cloud;}
 @GetMapping public List<VideoResponse> all(){return repo.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt")).stream().map(VideoResponse::from).toList();}
 @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @PreAuthorize("hasRole('ADMIN')") public VideoResponse create(@RequestParam String title,@RequestParam(required=false,defaultValue="")String description,@RequestParam String category,@RequestParam(defaultValue="false")boolean featured,@RequestPart MultipartFile video)throws Exception{Map m=cloud.upload(video);Video v=new Video();v.setTitle(title);v.setDescription(description);v.setCategory(category);v.setFeatured(featured);v.setVideoUrl((String)m.get("secure_url"));v.setPublicId((String)m.get("public_id"));v.setThumbnailUrl(v.getVideoUrl().replace("/upload/","/upload/so_1/").replace(".mp4",".jpg"));return VideoResponse.from(repo.save(v));}
 @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public ResponseEntity<Void> delete(@PathVariable Long id)throws Exception{Video v=repo.findById(id).orElseThrow();cloud.delete(v.getPublicId());repo.delete(v);return ResponseEntity.noContent().build();}
}
